+*, *::before, *::after {
+  box-sizing: border-box;
+  margin: 0;
+  padding: 0;
+}
+
+:root {
+  --bg-page: #0d0f14;
+  --bg-card: #161b24;
+  --bg-card-hover: #1c2333;
+  --border: #2a3348;
+  --border-open: #4a6fa5;
+  --accent: #5b8dd9;
+  --accent-glow: rgba(91, 141, 217, 0.18);
+  --text-primary: #e8ecf4;
+  --text-secondary: #8a96ab;
+  --text-answer: #c5cdd9;
+  --radius: 10px;
+  --transition: 0.22s ease;
+}
+
+body {
+  background: var(--bg-page);
+  color: var(--text-primary);
+  font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
+  line-height: 1.6;
+  min-height: 100vh;
+  padding: 48px 20px 80px;
+}
+
+.page-header {
+  text-align: center;
+  margin-bottom: 48px;
+}
+
+.page-header .paw {
+  font-size: 2.8rem;
+  display: block;
+  margin-bottom: 12px;
+  animation: sway 3s ease-in-out infinite;
+}
+
+@keyframes sway {
+  0%, 100% { transform: rotate(-6deg); }
+  50% { transform: rotate(6deg); }
+}
+
+.page-header h1 {
+  font-size: 2.4rem;
+  font-weight: 700;
+  letter-spacing: -0.5px;
+  background: linear-gradient(135deg, #7eb3f7 0%, #5b8dd9 50%, #9d6df0 100%);
+  -webkit-background-clip: text;
+  -webkit-text-fill-color: transparent;
+  background-clip: text;
+}
+
+.page-header p {
